#include "SpatialServiceRegistry.hpp"
namespace elysium::spatial {void SpatialServiceRegistry::declareDependency(ServiceKind a,ServiceKind b){deps_[a].push_back(b);}void SpatialServiceRegistry::invalidate(DirtyRequest d){dirty_.push_back(d);for(auto k:deps_[d.kind])dirty_.push_back({k,d.region,d.causeRevision});}std::vector<DirtyRequest>SpatialServiceRegistry::drainDirty(){std::sort(dirty_.begin(),dirty_.end(),[](auto&a,auto&b){if(a.causeRevision!=b.causeRevision)return a.causeRevision<b.causeRevision;return std::uint8_t(a.kind)<std::uint8_t(b.kind);});auto d=std::move(dirty_);dirty_.clear();return d;}bool SpatialServiceRegistry::publish(Snapshot s,std::string&w){auto i=snapshots_.find(s.kind);if(i!=snapshots_.end()&&s.revision<i->second.revision){w="stale snapshot";return false;}snapshots_[s.kind]=s;return true;}std::optional<Snapshot>SpatialServiceRegistry::snapshot(ServiceKind k)const{auto i=snapshots_.find(k);if(i==snapshots_.end())return std::nullopt;return i->second;}}
